import{t as e}from"./jsx-runtime-lw2jiZar.js";import{C as t,F as n,M as r,N as i,O as a,P as o,T as s,_ as c,b as l,j as u,k as d,w as f,x as p}from"./shared-DoR5oW6-.js";import{t as m}from"./git-branch--KUP4I0u.js";import{M as h}from"./index-ChLJS9_n.js";var g=e();function _({module:e}){return(0,g.jsxs)(i,{children:[(0,g.jsx)(r,{variant:`project`,chip:e??`Блок 12 · Архитектура, тесты и релиз Planner API`,title:`Сквозная приёмка: один ресурс через весь API`,intro:`У нас уже есть проверки отдельных операций и правил. Теперь проследим один фактический id через запросы, ошибки и повторное чтение, затем подтвердим тот же путь на работающем сервере.`,tags:[{icon:(0,g.jsx)(m,{size:14}),label:`один ресурс во времени`},{icon:(0,g.jsx)(h,{size:14}),label:`общие данные`}]}),(0,g.jsx)(n,{link:`Базовые HTTP-тесты и проверки отдельных правил уже есть; теперь свяжем операции вокруг одного ресурса и общего состояния.`,boundary:`Сквозной тест не заменяет проверки границ и не доказывает доступность работающего TCP-сервера.`}),(0,g.jsxs)(o,{number:`00`,title:`От отдельных гарантий к одной истории`,children:[(0,g.jsx)(a,{children:`У нас уже есть работающий Planner API и проверки отдельных операций, границ и прикладного ядра. Теперь свяжем эти гарантии во времени и проверим, что одна задача остаётся согласованной от создания до удаления.`}),(0,g.jsx)(d,{variant:`connected`,items:[{title:`Точка старта`,description:`Восемь HTTP-операций используют прежние Task, PlannerService и JsonStorage; базовые тесты и проверки отдельных правил уже существуют.`},{title:`Новый вопрос`,description:`Сохраняется ли правильное поведение, когда несколько запросов меняют один и тот же ресурс, а между ними происходит отказ?`},{title:`Результат`,description:`Мы проверим одну задачу сквозным HTTP-сценарием, сравним её с соседней задачей и повторим путь через настоящий сервер.`}]}),(0,g.jsx)(`p`,{children:`Начнём не с нового API и не с повторного CRUD. Мы используем то же приложение, те же маршруты и общий источник состояния. Связанность здесь означает, что следующий запрос наблюдает результат предыдущего, а не получает заново подготовленный список.`}),(0,g.jsx)(`p`,{children:`Сначала разберём примеры на независимой записи бронирования. Затем перенесём способ рассуждения в Planner. Так новый материал объясняет доказательство целого пути, но не подменяет практику готовым тестом.`})]}),(0,g.jsxs)(o,{number:`01`,title:`Тест операции и сквозной сценарий отвечают на разные вопросы`,children:[(0,g.jsx)(a,{children:`Отдельный тест проверяет локальное правило, а workflow проверяет переходы между настоящими HTTP-операциями.`}),(0,g.jsx)(`p`,{children:`Тест отдельной операции проверяет локальное правило: например, что обновление сохраняет идентификатор или что ошибочный ввод отклоняется до записи. Такой тест короток и точно указывает на сломанное правило. Он обычно готовит одно состояние и проверяет один результат.`}),(0,g.jsx)(`p`,{children:`Сквозной сценарий отвечает на другой вопрос: могут ли настоящие HTTP-операции пройти одну историю через то же приложение и один источник данных? Он проверяет не только отдельные ответы, но и переходы между ними. Если POST создал ресурс, последующий GET должен найти его, PUT заменить нужные поля, а PATCH изменить только переданные.`}),(0,g.jsx)(`p`,{children:`Представим маршрут поездки. Проверка отдельных станций подтверждает, что каждая станция работает. Сквозной тест похож на поездку пассажира от начала до конца: порядок остановок и один билет связывают их в общий путь. Здесь остановки соответствуют запросам, билет соответствует идентификатору ресурса, а порядок запросов сохраняет историю изменения. У аналогии есть граница: тест проходит в изолированном приложении, а не проверяет реальную сеть или доступность сервера по TCP.`}),(0,g.jsx)(`p`,{children:`Оставим оба вида доказательств. Сквозной тест не заменяет проверки границ из предыдущего занятия и не обязан повторять каждый вариант каждого поля. Он показывает, что проверенные части не потеряли связь при совместной работе.`}),(0,g.jsx)(s,{question:`Что лучше покажет, что изменился именно выбранный заказ, а контрольный заказ не затронут?`,left:{title:`Проверить только общее количество`,code:`assert order_stats()["total"] == 2`,note:`Количество может не измениться, даже если обновилась не та запись.`},right:{title:`Сверить две записи и общий итог`,code:`assert get_order(order_id) == expected
assert get_order(control_id) == control_before
assert order_stats() == expected_stats`,note:`Мы видим целевое изменение, неизменность соседа и ожидаемое состояние коллекции.`},preferred:`right`,explanation:`Мы оставляем короткие проверки отдельных правил, а workflow добавляет доказательство их совместной работы. Контрольная запись помогает заметить слишком широкое изменение.`})]}),(0,g.jsxs)(o,{number:`02`,title:`Одна история использует одно тестовое состояние`,children:[(0,g.jsx)(a,{children:`Мы подготавливаем исходную точку один раз и выполняем запросы последовательно. Изменение остаётся доступным следующему запросу того же сценария.`}),(0,g.jsx)(`p`,{children:`В примере с бронированием сервер возвращает идентификатор при создании записи. Следующий запрос использует его для изменения, а чтение после изменения показывает актуальное состояние. Мы не переустанавливаем исходные данные перед каждым запросом: так мы бы превратили одну историю в набор несвязанных эпизодов.`}),(0,g.jsx)(`p`,{children:`Порядок независимого примера виден на схеме: создаём бронь, берём выданный id, меняем бронь по этому id и снова читаем тот же ресурс. Фрагменты показывают порядок действий, а не код для запуска.`}),(0,g.jsx)(f,{title:`Соберём порядок запросов`,prompt:`В условном сервисе бронирования мы сначала создаём запись, затем используем её id. Расположите шаги по порядку. Это схема, не запускаемый код.`,pieces:[{id:`create`,code:`response = POST /orders`},{id:`id`,code:`order_id = response["id"]`},{id:`change`,code:`response = PATCH /orders/{order_id}`},{id:`read`,code:`reservation = GET /orders/{order_id}`}],correctOrder:[`create`,`id`,`change`,`read`],explanation:`Мы сначала получаем выданный сервером id, затем используем его для изменения и читаем ту же бронь после изменения.`,incorrectExplanation:`Мы не можем взять id до создания; без чтения после изменения не увидим его сохранённое состояние.`}),(0,g.jsx)(`p`,{children:`В Planner мы пройдём один путь: создание, чтение, полная замена, частичное изменение, удаление и подтверждение отсутствия. Между действиями мы не сбрасываем тестовый файл, не создаём второе приложение и не повторяем CRUD отдельной функцией.`}),(0,g.jsxs)(`figure`,{className:`lesson-infographic lesson-diagram lesson-diagram--vertical`,"aria-describedby":`planner-workflow-description`,children:[(0,g.jsx)(`figcaption`,{className:`lesson-diagram-caption`,children:`Один id через весь HTTP-договор`}),(0,g.jsxs)(`div`,{className:`lesson-diagram-flow`,role:`group`,"aria-label":`Последовательность запросов сверху вниз для одной задачи`,children:[(0,g.jsxs)(`div`,{className:`lesson-diagram-node`,children:[(0,g.jsx)(`h3`,{children:`Создать`}),(0,g.jsx)(`code`,{children:`POST /tasks`}),(0,g.jsx)(`p`,{children:`201, серверный id`})]}),(0,g.jsxs)(`div`,{className:`lesson-diagram-connector`,children:[(0,g.jsx)(`span`,{children:`id из ответа`}),(0,g.jsx)(`span`,{className:`lesson-diagram-arrow`,"aria-hidden":`true`})]}),(0,g.jsxs)(`div`,{className:`lesson-diagram-node`,children:[(0,g.jsx)(`h3`,{children:`Прочитать`}),(0,g.jsx)(`code`,{children:`GET /tasks/{task_id}`}),(0,g.jsx)(`p`,{children:`200, та же задача`})]}),(0,g.jsxs)(`div`,{className:`lesson-diagram-connector`,children:[(0,g.jsx)(`span`,{children:`тот же id`}),(0,g.jsx)(`span`,{className:`lesson-diagram-arrow`,"aria-hidden":`true`})]}),(0,g.jsxs)(`div`,{className:`lesson-diagram-node`,children:[(0,g.jsx)(`h3`,{children:`Заменить`}),(0,g.jsx)(`code`,{children:`PUT /tasks/{task_id}`}),(0,g.jsx)(`p`,{children:`200, полный набор полей`})]}),(0,g.jsxs)(`div`,{className:`lesson-diagram-connector`,children:[(0,g.jsx)(`span`,{children:`тот же id`}),(0,g.jsx)(`span`,{className:`lesson-diagram-arrow`,"aria-hidden":`true`})]}),(0,g.jsxs)(`div`,{className:`lesson-diagram-node`,children:[(0,g.jsx)(`h3`,{children:`Изменить`}),(0,g.jsx)(`code`,{children:`PATCH /tasks/{task_id}`}),(0,g.jsx)(`p`,{children:`200, только переданные поля`})]}),(0,g.jsxs)(`div`,{className:`lesson-diagram-connector`,children:[(0,g.jsx)(`span`,{children:`тот же id`}),(0,g.jsx)(`span`,{className:`lesson-diagram-arrow`,"aria-hidden":`true`})]}),(0,g.jsxs)(`div`,{className:`lesson-diagram-node`,children:[(0,g.jsx)(`h3`,{children:`Удалить`}),(0,g.jsx)(`code`,{children:`DELETE /tasks/{task_id}`}),(0,g.jsx)(`p`,{children:`204, пустое тело`})]}),(0,g.jsxs)(`div`,{className:`lesson-diagram-connector`,children:[(0,g.jsx)(`span`,{children:`проверка отсутствия`}),(0,g.jsx)(`span`,{className:`lesson-diagram-arrow`,"aria-hidden":`true`})]}),(0,g.jsxs)(`div`,{className:`lesson-diagram-node`,children:[(0,g.jsx)(`h3`,{children:`Подтвердить`}),(0,g.jsx)(`code`,{children:`GET /tasks/{task_id}`}),(0,g.jsx)(`p`,{children:`404, задачи нет`})]})]}),(0,g.jsx)(`p`,{className:`lesson-diagram-caption`,id:`planner-workflow-description`,children:`Читаем сверху вниз: каждый запрос обращается к одной задаче. После удаления новое чтение подтверждает ожидаемое отсутствие.`})]}),(0,g.jsx)(`p`,{children:`Схема показывает главную последовательность, но не заменяет проверки соседней задачи и общей stats. Эти наблюдения помогают понять, что все маршруты продолжают использовать один Planner и одну запись хранилища.`})]}),(0,g.jsxs)(o,{number:`03`,title:`Идентификатор приходит из ответа сервера`,children:[(0,g.jsx)(a,{children:`Сценарий связывает запросы по идентификатору ресурса, а не по номеру позиции или ожидаемому числу.`}),(0,g.jsx)(`p`,{children:`Идентификатор создаваемой задачи назначает сервер. Даже если пустое тестовое хранилище сейчас обычно выдаёт первое значение, тест не должен называть его заранее. Такой тест случайно связывает себя с порядком запуска или начальным содержимым и может обращаться не к той записи.`}),(0,g.jsx)(`p`,{children:`В отдельном примере с каталогом книг мы читаем id из ответа POST и передаём его следующему GET. Это подтверждает не позицию в списке, а адрес именно созданного ресурса. После удаления максимальный id может быть использован повторно, поэтому отсутствие проверяем отдельным запросом и не создаём после него новую задачу с предположением об исторической уникальности.`}),(0,g.jsx)(t,{code:`created = client.post("/books", json={"title": "Atlas"})
book_id = 8
response = client.get(f"/books/{book_id}")`,question:`Какую строку мы заменим, чтобы GET обратился именно к только что созданной книге?`,options:[`book_id = created.json()["id"]`,`book_id = len(created.json())`,`book_id = 0`],correctIndex:0,explanation:`Мы берём id из ответа POST. Сервер назначает идентификатор, поэтому фиксированное число или позиция ответа не подтверждают, что читается созданная запись.`,fix:`book_id = created.json()["id"]`}),(0,g.jsx)(`p`,{children:`Главная задача не должна быть единственной. Мы создаём ещё одну контрольную задачу и сохраняем оба фактических id. Контрольная запись помогает увидеть, если update или delete случайно затронул соседа. Если проверять только число элементов, потеря одной задачи и случайное добавление другой могут дать то же количество.`})]}),(0,g.jsxs)(o,{number:`04`,title:`Ответ и новое чтение дают разные доказательства`,children:[(0,g.jsx)(a,{children:`Ответ подтверждает форму HTTP-результата, а повторное чтение показывает состояние, доступное следующему запросу.`}),(0,g.jsx)(`p`,{children:`Статус и body ответа подтверждают, что маршрут вернул обещанную форму. Последующее чтение подтверждает, что изменение доступно следующему запросу. Для POST это отдельный GET созданного id; для PUT и PATCH это GET после обновления. При DELETE успешный ответ имеет статус 204 и пустое тело, поэтому JSON из такого ответа читать не нужно.`}),(0,g.jsx)(`p`,{children:`Это похоже на чек после покупки. Чек показывает, что касса оформила операцию. Но чтобы подтвердить, что товар появился в заказе, мы отдельно открываем сам заказ. Граница аналогии в том, что HTTP-ответ всё равно остаётся важной частью договора: проверка чтения не заменяет проверку статуса и body.`}),(0,g.jsx)(`p`,{children:`В изолированном примере две переменные могут показать разные значения:`}),(0,g.jsx)(c,{code:`tasks = [{"id": 4, "title": "Draft"}]
saved_view = tasks[0].copy()
response_body = {"id": 4, "title": "Reviewed"}
print(response_body["title"], saved_view["title"], tasks[0]["title"])`,output:`Reviewed Draft Draft`,hint:`Мы читаем три значения отдельно: body ответа, копию и исходный список.`}),(0,g.jsx)(`p`,{children:`Вывод Reviewed Draft Draft показывает, что правдоподобный response body не гарантирует изменения общего состояния. Это обычный пример со словарями, не запуск Planner API. В тесте мы сопоставляем контракт ответа, новое чтение и состояние после действия.`}),(0,g.jsx)(`p`,{children:`Запрос к списку показывает выбранные записи, а GET /stats считает полный источник независимо от фильтра списка. Эти представления помогают найти расхождение, но не являются отдельными хранилищами.`})]}),(0,g.jsxs)(o,{number:`05`,title:`Контрольная задача обнаруживает слишком широкое изменение`,children:[(0,g.jsx)(a,{children:`Мы проверяем не только целевой ресурс, но и соседнюю запись, которая не должна измениться.`}),(0,g.jsx)(`p`,{children:`Для PUT мы отправляем полную схему изменяемых полей, сохраняем прежний id и проверяем целевую задачу повторным чтением. Для PATCH мы передаём только is_done=False. Это значение должно примениться, хотя оно ложное: проверка наличия поля отличается от проверки истинности значения. Название и приоритет при этом остаются прежними.`}),(0,g.jsx)(`p`,{children:`После каждой важной точки мы проверяем контрольную запись целиком. Сравнение только stats может пропустить замену не той задачи, потерю title или изменение приоритета. Полная запись соседа даёт более точный ответ о побочном эффекте. Сами stats полезны как независимое наблюдение общего состояния: total, open и done должны совпасть с известными переходами.`}),(0,g.jsx)(`p`,{children:`В независимом примере склада проверка общего количества может не заметить, что заказали не ту коробку. Чтение выбранного заказа и проверка контрольного заказа отвечают на вопрос о конкретных ресурсах. Это не требует создавать новые endpoints: мы используем чтение и stats, уже предусмотренные договором Planner API.`}),(0,g.jsx)(p,{question:`Какое наблюдение покажет, что мы изменили нужный заказ, а не соседний?`,hint:`Сравним не только общий счётчик.`,answer:(0,g.jsx)(`p`,{children:`Мы повторно прочитаем целевой ресурс и контрольную запись, а затем сверим общий итог. Один stats не показывает, какая именно запись изменилась.`})})]}),(0,g.jsxs)(o,{number:`06`,title:`Ожидаемая ошибка не должна обрывать проверку состояния`,children:[(0,g.jsx)(a,{children:`Мы включаем отказ в сценарий и продолжаем чтение, чтобы доказать отсутствие частичного изменения.`}),(0,g.jsx)(`p`,{children:`Ошибка может быть правильным результатом запроса. Невалидное тело получает 422 до изменения существующей задачи. Корректный запрос к отсутствующему id получает 404. Эти ответы различают неподходящий ввод и отсутствие ресурса. Ошибка программы или хранилища не должна маскироваться под ожидаемый 404.`}),(0,g.jsx)(`p`,{children:`В середине сценария мы отправляем невалидное частичное изменение и неполный PUT. После каждого отказа повторное чтение должно вернуть ту же полную задачу, список соседа не меняется, а stats остаются прежними. Если проверить только статус 422, тест не заметит частичную запись, произошедшую до ответа.`}),(0,g.jsx)(`p`,{children:`После отказа сценарий продолжается. Валидный PATCH с false должен сработать, затем DELETE главной задачи должен вернуть пустой 204. Повторное чтение и подходящие запросы к уже отсутствующему id должны дать 404, а контрольная задача должна остаться доступной. Ожидаемый отказ стал частью успешной истории, потому что состояние сохранилось и дальнейшие действия работают.`}),(0,g.jsx)(l,{question:`Мы отправили корректное тело PUT для целого id, которого нет. Какой ответ различает отсутствие задачи и неправильный ввод?`,options:[`422`,`404`,`204`],correctIndex:1,explanation:`Мы получаем 404: тело и id имеют допустимую форму, но ресурс отсутствует. Невалидное тело отклоняется с 422 до действия.`})]}),(0,g.jsxs)(o,{number:`07`,title:`TestClient и Postman проходят разные границы`,children:[(0,g.jsx)(a,{children:`Автоматический тест и ручной запрос проходят один HTTP-договор, но обращаются к разным процессам и разным файлам состояния.`}),(0,g.jsx)(`p`,{children:`TestClient отправляет запросы приложению напрямую через ASGI-интерфейс. Для такого теста не нужно запускать Uvicorn и открывать TCP-порт. Это надёжная проверка HTTP-маршрутов и взаимодействия с тестовым сервисом, но она не доказывает, что запущенный сервер доступен клиенту через сеть.`}),(0,g.jsx)(`p`,{children:`В каждом тесте используем знакомую function-scoped fixture с отдельным JsonStorage в tmp_path. Все запросы одного workflow обращаются к одному тестовому файлу, а следующий тест получает чистое состояние. Fixture временно подключает тестовый PlannerService через app.state.planner и восстанавливает прежний сервис после завершения. Клиент закрывается до восстановления. Рабочий data/tasks.json не очищается и не используется автотестом.`}),(0,g.jsx)(`p`,{children:`Postman проверяет работающий Uvicorn и рабочий JSON, который уже может содержать задачи. Поэтому сначала читаем baseline stats N/O/D, где N это total, O это open, D это done. Затем считаем относительное изменение: два новых открытых элемента дают N+2/O+2/D; перевод главного в done даёт N+2/O+1/D+1; PATCH с false возвращает N+2/O+2/D; удаление главного даёт N+1/O+1/D. Числа исходного файла и идентификаторы заранее не задаём.`}),(0,g.jsx)(`p`,{children:`Мы запускаем workflow отдельно и вместе с набором тестов. Затем повторяем путь через сохранённую Planner collection, начиная с фактического baseline CLI и сохраняя все запросы последовательными. Так pytest проверяет изоляцию, а Postman подтверждает работающий сервер и общий рабочий файл.`}),(0,g.jsx)(`p`,{children:`В collection уже добавлены post-response scripts: Postman запускает их после получения ответа. Через pm.response сценарий проверяет status и выбранные данные ответа: например, что POST вернул 201 и поля задачи, GET прочитал тот же id, stats изменились на ожидаемую величину, DELETE вернул пустой 204, а запрос к удалённой задаче получил 404. Скрипты не отправляют следующий запрос и не исправляют состояние сервера: они проверяют ответ текущего запроса.`}),(0,g.jsx)(`p`,{children:`Когда сценарий 67 получает исходную stats, скрипт сохраняет значения в переменные коллекции workflow_total_before, workflow_open_before и workflow_done_before. Ответы двух POST дают workflow_control_id и workflow_target_id; следующие URL используют их как {{workflow_control_id}} и {{workflow_target_id}}. Это обычные значения внутри Postman collection, не переменные Python или окружения Windows. В других группах collection значения created_id, roundtrip_id и delete_id хранят id созданных задач, а before_noop_patch хранит JSON-ответ перед проверкой PATCH без изменений.`}),(0,g.jsx)(`p`,{children:`Если проверочный script отключён или переменная не заполнилась, продолжаем вручную. После POST открываем Body ответа, копируем фактическое поле id и в переменных collection задаём, например, workflow_target_id; для контрольной задачи отдельно задаём workflow_control_id. Можно также подставить число прямо в URL следующего GET, например GET {{base_url}}/tasks/123. Затем сверяем id и запись в ответе GET. Ошибка проверки не отменяет уже выполненный POST, поэтому сначала читаем ответ, а не отправляем создание повторно вслепую.`})]}),(0,g.jsxs)(o,{number:`08`,title:`Что мы будем делать в практике`,children:[(0,g.jsx)(a,{children:`В практике мы добавим связанную проверку к существующему приложению и отдельно повторим наблюдаемый путь через Postman.`}),(0,g.jsx)(d,{variant:`connected`,items:[{title:`Напишем`,description:`Напишем tests/test_workflow.py, который обращается к настоящему приложению и сохраняет один тестовый JsonStorage между запросами сценария.`},{title:`Сверим`,description:`Проследим фактический id через GET, PUT, PATCH и DELETE; список, stats и контрольная задача подтвердят границы изменений.`},{title:`Повторим`,description:`Пройдём те же операции в Postman через работающий сервер, используя baseline рабочего файла и относительные значения stats.`}]}),(0,g.jsx)(`p`,{children:`Эта работа дополняет проверки отдельных маршрутов и правил, а не заменяет их. Успехом будет один прослеживаемый HTTP-сценарий с ожидаемыми ответами, сохранёнными данными до отказа и корректным состоянием после каждого перехода.`}),(0,g.jsx)(`p`,{children:`На следующем шаге мы проверим передачу всего проекта из чистого окружения. Там мы подтвердим запуск по README и воспроизводимость версии; создавать CRUD заново не потребуется.`}),(0,g.jsx)(u,{text:`Проследим одну задачу через API и подтвердим её состояние.`})]})]})}export{_ as Lesson67};